import sys

data = sys.stdin.read().split()
n = int(data[0])
start = (int(data[1]), int(data[2]))
goal = (int(data[3]), int(data[4]))
seen = {start}
layer = {start}
steps = 0
ans = -1
while layer:
    if goal in layer:
        ans = steps
        break
    nxt = set()
    for (x, y) in layer:
        for dx in (-2, -1, 1, 2):
            for dy in (-2, -1, 1, 2):
                if abs(dx) != abs(dy):
                    p = (x + dx, y + dy)
                    if 1 <= p[0] <= n and 1 <= p[1] <= n and p not in seen:
                        seen.add(p)
                        nxt.add(p)
    layer = nxt
    steps += 1
print(ans)

